(14782, '3270', NULL, 1, 191, '58a43578317583313c2216ffdcf95472.pdf', '2024-06-07', NULL, 'no', NULL, 'SE REALIZA LIMPIEZA Y DESINFECCION DEL EQUIPO, SE HACE INSPECCION VISUAL Y ESTRUCTURAL DEL EQUIPO Y SE CONFIRMA QUE SE ENCUENTRA EN CORRECTO ESTADO, SE HACEN\r\nPRUEBAS DE FUNCIONAMIENTO CON EQUIPO PATRON Y EL EQUIPO RESPONDE CORRECTAMENTE, SE HACE CONSTANCIA DEL CORRECTO FUNCIONAMIENTO DE LA BATERIA, SE HACE\r\nENTREGA DEL EQUIPO OPERATIVO EN EL AREA DEL SERVICIO.', 20),
(14783, '3189', NULL, 1, 828, '8506bd7f296d62ed0537acc436f00e5c.pdf', '2024-06-05', NULL, 'no', NULL, 'SE REALIZA MANTENIMIENTO PREVENTIVO, LIMPIEZA Y DESINFECCION DEL EQUIPO DE MANERA INTERNA Y EXTERNA, SE HACE INSPECCION VISUAL Y ESTRUCTURAL DEL EQUIPO Y SE\r\nCONFIRMA QUE SE ENCUENTRA EN CORRECTO ESTADO, SE HACEN PRUEBAS DE FUNCIONAMIENTO GENERAL CON EQUIPO PATRON Y TRABAJA CORRECTAMENTE, SE COMPRUEBA EL\r\nESTADO DE LA BATERIA, FUNCIONA CORRECTAMENTE, PERO SE RECOMIENDA REALIZAR CAMBIO DE BATERIA, SE HACE ENTREGA DEL EQUIPO OPERATIVO EN EL AREA DEL SERVICIO', 20),
(14784, '3454', NULL, 1, 275, '0a3312c01762ec6558eac78e7c1025bb.pdf', '2024-07-03', NULL, 'no', NULL, 'SE REALIZA LIMPIEZA Y DESINFECCION DEL EQUIPO DE MANERA INTERNA Y EXTERNA, SE HACE INSPECCION VISUAL Y ESTRUCTURAL DEL EQUIPO Y SE CONFIRMA QUE SE ENCUENTRA EN\r\nCORRECTO ESTADO, SE HACEN PRUEBAS DE FUNCIONAMIENTO GENERAL CON EQUIPO PATRON Y EL EQUIPO RESPONDE CORRECTAMENTE EN LAS DISTINTAS VARIABLES, SE HACE\r\nENTREGA DEL EQUIPO OPERATIVO EN EL AREA DEL SERVICIO.', 20),
