(16720, '4280', NULL, 1, 201, '7c9784be6108269128683b35c4fd7d0e.pdf', '2024-12-10', NULL, 'no', NULL, 'SE REALIZA LIMPIEZA Y DESINFECCION DEL EQUIPO DE MANERA INTERNA Y EXTERNA, SE HACE INSPECCION VISUAL Y ESTRUCTURAL DEL EQUIPO Y SE CONFIRMA QUE SE ENCUENTRA EN CORRECTO ESTADO, SE HACEN PRUEBAS DE FUNCIONAMIENTO GENERAL CON EQUIPO PATRON Y TRABAJA CORRECTAMENTE, SE EVIDENCIA QUE LOS CABLES ECG SE ENCUENTRAN DETERIORADOS, SE RECOMIENDA REALIZAR CAMBIO, SE COMPRUEBA EL ESTADO DE LA BATERIA, FUNCIONA CORRECTAMENTE, PERO SE RECOMIENDA REALIZAR CAMBIO DE BATERIA, SE HACE ENTREGA DEL EQUIPO OPERATIVO EN EL AREA DEL SERVICIO.', 20),
(16721, '4299', NULL, 1, 1987, '61a04fb3abc9e096c9ad29767b114519.pdf', '2024-12-13', NULL, 'no', NULL, 'SE REALIZA MANTENIMIENTO PREVENTIVO, LIMPIEZA Y DESINFECCION DEL EQUIPO DE MANERA INTERNA Y EXTERNA, SE HACE INSPECCION VISUAL Y ESTRUCTURAL DEL EQUIPO Y SE CONFIRMA QUE SE ENCUENTRA EN CORRECTO ESTADO, SE LUBRICAN SUS PARTES MECANICAS, SE REALIZAN PRUEBAS DE FUNCIONAMIENTO. SE ENTREGA EQUIPO FUNCIONAL EN EL SERVICIO, CABE RESALTAR QUE EL EQUIPO REQUIERE CAMBIO DE LENTES.', 20),
(16722, '4331', NULL, 1, 6248, '4d640c12bf299d123f279161841b81e3.pdf', '2024-12-18', NULL, 'no', NULL, 'SE REALIZA LIMPIEZA Y DESINFECCION DEL EQUIPO DE MANERA INTERNA Y EXTERNA, SE HACE INSPECCION VISUAL Y ESTRUCTURAL DEL EQUIPO Y SE CONFIRMA QUE SE ENCUENTRA EN CORRECTO ESTADO, SE HACEN PRUEBAS DE FUNCIONAMIENTO GENERAL CON MASAS PATRON, FINALMENTE SE HACE ENTREGA DEL EQUIPO OPERATIVO EN EL AREA DEL SERVICIO.', 20),
(16723, '4336', NULL, 1, 4175, 'ff344c55b0042505904fc882550f6f5c.pdf', '2024-12-23', NULL, 'no', NULL, 'SE REALIZA LIMPIEZA Y DESINFECCION DEL EQUIPO DE MANERA INTERNA Y EXTERNA, SE HACE INSPECCION VISUAL Y ESTRUCTURAL DEL EQUIPO Y SE CONFIRMA QUE SE ENCUENTRA EN CORRECTO ESTADO, SE HACEN PRUEBAS DE FUNCIONAMIENTO GENERAL Y TRABAJA CORRECTAMENTE, SE COMPRUEBA QUE EL EQUIPO DETECTA DE MANERA EFECTIVA LA POSICION DEL TUBO DE ENSAYO, SE EVIDENCIA QUE EL EQUIPO CALIENTA CORRECTAMENTE, SE HACE ENTREGA DEL EQUIPO OPERATIVO EN EL AREA DEL SERVICIO.', 20),
